export type DocumentKind = "note" | "dialogue";

export interface TextDigest {
  summary: string;
  labels: string[];
}

export function digestText(text: string, kind: DocumentKind): TextDigest {
  if (kind !== "note" && kind !== "dialogue") {
    throw new RangeError("unsupported document kind");
  }

  const normalized = text.replace(/\r\n?/g, "\n");
  if (normalized.trim().length === 0) {
    return { summary: "", labels: [] };
  }

  const units = kind === "note"
    ? normalized.split(/[.!?]+/).map((value) => value.trim()).filter(Boolean)
    : normalized.split("\n")
        .map((value) => value.trim().replace(/^[^:\n]+:\s*/, "").trim())
        .filter(Boolean);

  const found = new Set<string>();
  if (kind === "note") {
    for (const match of normalized.matchAll(/#([A-Za-z0-9_-]+)/g)) {
      found.add(match[1].toLowerCase());
    }
  } else {
    for (const match of normalized.matchAll(/\[skill:\s*([^\]\s](?:[^\]]*?[^\]\s])?)\s*\]/gi)) {
      found.add(match[1].trim().toLowerCase());
    }
  }

  return {
    summary: units.slice(0, 2).join(" "),
    labels: [...found],
  };
}

