import { digestText } from './solution';

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function deepEqual(actual: unknown, expected: unknown, message: string): void {
  assert(JSON.stringify(actual) === JSON.stringify(expected), `${message}: ${JSON.stringify(actual)}`);
}
function throwsRangeError(action: () => void, message: string): void {
  let error: unknown;
  try { action(); } catch (caught) { error = caught; }
  assert(error instanceof RangeError, message);
}

deepEqual(digestText('  First IDEA #Beta.\r\n second thought #alpha! Third #BETA? ', 'note'), {
  summary: 'First IDEA #Beta second thought #alpha',
  labels: ['alpha', 'beta'],
}, 'note summary and labels');

deepEqual(digestText('No tag #. Valid #A_1 and #z-z; trailing #ok!', 'note'), {
  summary: 'No tag # Valid #A_1 and #z-z; trailing #ok',
  labels: ['a_1', 'ok', 'z-z'],
}, 'note hashtag grammar and ordering');

deepEqual(digestText(
  ' Alice: Hello Team [skill: TypeScript ] \r\n Bob: Ship it [SKILL: leadership]\r\n Plain third line [skill:typescript]\r\n Eve: [skill:   ] [skill:]',
  'dialogue',
), {
  summary: 'Hello Team [skill: TypeScript ] Ship it [SKILL: leadership]',
  labels: ['leadership', 'typescript'],
}, 'dialogue prefixes, summary, and skill labels');

deepEqual(digestText('  \r\n\t\r\n ', 'note'), { summary: '', labels: [] }, 'empty note');
deepEqual(digestText('', 'dialogue'), { summary: '', labels: [] }, 'empty dialogue');
deepEqual(digestText('One...!! Two?', 'note'), { summary: 'One Two', labels: [] }, 'empty sentence units are ignored');

const source = 'Speaker: Keep Case [skill: Focus]';
const digest = digestText(source, 'dialogue');
digest.labels.push('caller-change');
deepEqual(digestText(source, 'dialogue'), {
  summary: 'Keep Case [skill: Focus]',
  labels: ['focus'],
}, 'returned label arrays are independent');

throwsRangeError(() => digestText('text', 'report' as never), 'invalid runtime kind must fail');

